  if(action==='tx-history-tab'){state.txHistoryTab=el.dataset.value;persist();render();return true;}
  if(action==='tx-accept')confirmAccept();
  else if(action==='tx-accept-charge'){if(!access('agent',['pending'],r))return true;state.txAcceptReturn=r.id;persist();closeModal();navigate('credits');}
  else if(action==='tx-do-accept'){if($$('[data-accept-consent]:checked').length!==2)return true;if(!access('agent',['pending'],r))return true;if(state.credits<1){confirmAccept();return true;}state.credits-=1;r.creditCharged=true;r.acceptedAt=now();r.status='accepted';emit(r,'accepted','도우미가 요청을 수락했어요',r.show+' · 도우미가 최종 조건을 작성할 차례예요.','user');persist();closeModal();navigate('detail',r.id);toast('요청을 수락했어요. 최종 조건을 작성해 주세요.');}
